#!/bin/bash
# BWA-MEM + Samtools sort workflow for Slurm job arrays
# INSTRUMENTED VERSION with pipewatch observability
# 
# Usage:
#   sbatch --array=1-10 run_instrumented.sh samples.txt reference.fa
#
# Generated by: pipewatch wrap run.sh -o run_instrumented.sh

set -euo pipefail

# === Pipewatch instrumentation ===
# Load obsrun for observability
OBSRUN_PATH="${OBSRUN_PATH:-$(which obsrun 2>/dev/null || echo '../../src/pipewatch/obsrun.sh')}"

# Export events to run-specific directory
export PIPEWATCH_EVENTS_FILE="${PIPEWATCH_EVENTS_DIR:-./pipewatch-events}/run.ndjson"

# Wrapper function for observability
pipewatch_wrap() {
    local step_name="$1"
    local sample_id="$2"
    local stdout_path="$3"
    local stderr_path="$4"
    shift 4
    local cmd="$*"
    
    if [ -x "$OBSRUN_PATH" ]; then
        PIPEWATCH_STEP_NAME="$step_name" \
        PIPEWATCH_SAMPLE_ID="$sample_id" \
        PIPEWATCH_STDOUT_PATH="$stdout_path" \
        PIPEWATCH_STDERR_PATH="$stderr_path" \
        "$OBSRUN_PATH" "$cmd"
    else
        echo "Warning: obsrun not found at $OBSRUN_PATH, running without observability" >&2
        eval "$cmd"
    fi
}

# === End Pipewatch instrumentation ===

# Input validation
if [ $# -lt 2 ]; then
    echo "Usage: $0 <samples.txt> <reference.fa>"
    echo ""
    echo "samples.txt format (tab-delimited):"
    echo "  sample_id    path_to_R1    path_to_R2"
    exit 1
fi

SAMPLES_FILE="$1"
REFERENCE="$2"
OUTPUT_DIR="${OUTPUT_DIR:-./output}"

# Create output directory
mkdir -p "$OUTPUT_DIR/logs"

# Get sample info for this array task
if [ -n "${SLURM_ARRAY_TASK_ID:-}" ]; then
    # Running as array job
    SAMPLE_LINE=$(sed -n "${SLURM_ARRAY_TASK_ID}p" "$SAMPLES_FILE")
else
    # Running as single job (for testing)
    SAMPLE_LINE=$(head -n1 "$SAMPLES_FILE")
fi

# Parse sample info
SAMPLE_ID=$(echo "$SAMPLE_LINE" | cut -f1)
R1=$(echo "$SAMPLE_LINE" | cut -f2)
R2=$(echo "$SAMPLE_LINE" | cut -f3)

echo "Processing sample: $SAMPLE_ID"
echo "R1: $R1"
echo "R2: $R2"
echo "Reference: $REFERENCE"

# Define output files
SORTED_BAM="$OUTPUT_DIR/${SAMPLE_ID}.sorted.bam"
STATS_FILE="$OUTPUT_DIR/${SAMPLE_ID}.flagstat"

# Step 1: Align with BWA and sort with samtools
# This step is now instrumented with obsrun
echo "[$SAMPLE_ID] Starting alignment..."

# Build the command that will be wrapped
ALIGN_CMD="bwa mem -t \${SLURM_CPUS_PER_TASK:-4} '${REFERENCE}' '${R1}' '${R2}' | \\
    samtools sort -@ \${SLURM_CPUS_PER_TASK:-4} -m 2G -o '${SORTED_BAM}' - && \\
    samtools index '${SORTED_BAM}'"

# Run with observability
srun \
    --job-name="align_${SAMPLE_ID}" \
    --output="$OUTPUT_DIR/logs/${SAMPLE_ID}_align.log" \
    --error="$OUTPUT_DIR/logs/${SAMPLE_ID}_align.err" \
    bash -c "
        set -euo pipefail
        $(declare -f pipewatch_wrap)
        $(declare -p OBSRUN_PATH PIPEWATCH_EVENTS_FILE)
        pipewatch_wrap 'align' '${SAMPLE_ID}' \\
            '$OUTPUT_DIR/logs/${SAMPLE_ID}_align.log' \\
            '$OUTPUT_DIR/logs/${SAMPLE_ID}_align.err' \\
            '${ALIGN_CMD}'
    "

echo "[$SAMPLE_ID] Alignment complete: $SORTED_BAM"

# Step 2: Generate statistics
echo "[$SAMPLE_ID] Generating statistics..."

STATS_CMD="samtools flagstat '${SORTED_BAM}' > '${STATS_FILE}' && \\
    samtools idxstats '${SORTED_BAM}' > '${OUTPUT_DIR}/${SAMPLE_ID}.idxstats'"

srun \
    --job-name="stats_${SAMPLE_ID}" \
    --output="$OUTPUT_DIR/logs/${SAMPLE_ID}_stats.log" \
    --error="$OUTPUT_DIR/logs/${SAMPLE_ID}_stats.err" \
    bash -c "
        set -euo pipefail
        $(declare -f pipewatch_wrap)
        $(declare -p OBSRUN_PATH PIPEWATCH_EVENTS_FILE)
        pipewatch_wrap 'stats' '${SAMPLE_ID}' \\
            '$OUTPUT_DIR/logs/${SAMPLE_ID}_stats.log' \\
            '$OUTPUT_DIR/logs/${SAMPLE_ID}_stats.err' \\
            '${STATS_CMD}'
    "

echo "[$SAMPLE_ID] Statistics written to: $STATS_FILE"
echo "[$SAMPLE_ID] Processing complete!"
echo ""
echo "Events written to: $PIPEWATCH_EVENTS_FILE"
